using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Tilemaps;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEditor.Animations;
using UnityEditor.U2D;
using UnityEngine.U2D;
using UnityEditor.Build.Reporting;
using UnityEngine.SceneManagement;

[Serializable] public class YoeSpriteSettings {public int frames=1,ppu=32,fps=10;public float pivotX=.5f,pivotY=.5f;public string filter="point";}
public static class YoeStudioBridge {
 static YoeSpriteSettings Settings(string state){string p="Assets/YOE/Art/"+state+".settings.json";return File.Exists(p)?JsonUtility.FromJson<YoeSpriteSettings>(File.ReadAllText(p)):new YoeSpriteSettings();}
 static string Root=>Directory.GetParent(Application.dataPath).FullName;
 static YoeGameSpec Spec=>JsonUtility.FromJson<YoeGameSpec>(File.ReadAllText(Path.Combine(Application.dataPath,"Resources/yoe-game.json")));
 static void Report(string name,string data){Directory.CreateDirectory(Path.Combine(Root,"YOE"));File.WriteAllText(Path.Combine(Root,"YOE",name),data);}
 static string Q(string s)=>"\""+s.Replace("\\","\\\\").Replace("\"","\\\"").Replace("\n"," ").Replace("\r"," ")+"\"";
 static void Folder(string path){if(AssetDatabase.IsValidFolder(path))return;Folder(Path.GetDirectoryName(path).Replace('\\','/'));AssetDatabase.CreateFolder(Path.GetDirectoryName(path).Replace('\\','/'),Path.GetFileName(path));}
 static Sprite Square(string name,Color color){string path="Assets/YOE/Art/"+name+".png";if(!File.Exists(path)){var tex=new Texture2D(32,32);var pixels=Enumerable.Repeat(color,1024).ToArray();tex.SetPixels(pixels);tex.Apply();File.WriteAllBytes(path,tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);}AssetDatabase.ImportAsset(path);Import(path);return AssetDatabase.LoadAssetAtPath<Sprite>(path);}
 static void Import(string path){var importer=AssetImporter.GetAtPath(path) as TextureImporter;if(importer==null)return;importer.textureType=TextureImporterType.Sprite;importer.spriteImportMode=SpriteImportMode.Single;var config=Settings(Path.GetFileNameWithoutExtension(path).Split('-')[0]);importer.spritePixelsPerUnit=Mathf.Clamp(config.ppu,8,100);importer.alphaIsTransparency=true;importer.filterMode=config.filter=="bilinear"?FilterMode.Bilinear:FilterMode.Point;importer.textureCompression=TextureImporterCompression.Uncompressed;var ts=new TextureImporterSettings();importer.ReadTextureSettings(ts);ts.spriteAlignment=(int)SpriteAlignment.Custom;ts.spritePivot=new Vector2(Mathf.Clamp01(config.pivotX),Mathf.Clamp01(config.pivotY));importer.SetTextureSettings(ts);importer.SaveAndReimport();}
 static GameObject SpriteObject(string name,Sprite sprite,Vector2 at,Vector2 scale,bool collider=false){var g=new GameObject(name);g.transform.position=at;g.transform.localScale=scale;var renderer=g.AddComponent<SpriteRenderer>();renderer.sprite=sprite;renderer.sortingOrder=1;if(collider)g.AddComponent<BoxCollider2D>();return g;}
 static AnimatorController Animations(Sprite fallback){Folder("Assets/YOE/Animations");string path="Assets/YOE/Animations/Hero.controller";if(File.Exists(path))AssetDatabase.DeleteAsset(path);var controller=AnimatorController.CreateAnimatorControllerAtPath(path);controller.AddParameter("Speed",AnimatorControllerParameterType.Float);AnimatorState idle=null,walk=null;
  foreach(string state in new[]{"idle","walk","run","jump","fall","attack","hurt","death","dash","interact","special"}){var frames=Directory.GetFiles("Assets/YOE/Art",state+"-*.png").OrderBy(x=>x).Select(x=>AssetDatabase.LoadAssetAtPath<Sprite>(x.Replace('\\','/'))).Where(x=>x).ToArray();if(frames.Length==0)frames=new[]{fallback};var config=Settings(state);if(File.Exists("Assets/YOE/Art/"+state+".settings.json"))frames=frames.Take(Mathf.Clamp(config.frames,1,32)).ToArray();float fps=Mathf.Clamp(config.fps,1,24);var clip=new AnimationClip{name=state,frameRate=fps};var settings=AnimationUtility.GetAnimationClipSettings(clip);settings.loopTime=!new[]{"death","hurt","attack"}.Contains(state);AnimationUtility.SetAnimationClipSettings(clip,settings);var binding=new EditorCurveBinding{path="",type=typeof(SpriteRenderer),propertyName="m_Sprite"};var keys=frames.Select((s,i)=>new ObjectReferenceKeyframe{time=i/fps,value=s}).ToArray();AnimationUtility.SetObjectReferenceCurve(clip,binding,keys);string cp="Assets/YOE/Animations/"+state+".anim";if(File.Exists(cp))AssetDatabase.DeleteAsset(cp);AssetDatabase.CreateAsset(clip,cp);var ast=controller.layers[0].stateMachine.AddState(state);ast.motion=clip;if(state=="idle")idle=ast;if(state=="walk")walk=ast;if(state!="idle"&&state!="walk"){controller.AddParameter(state,AnimatorControllerParameterType.Trigger);var tr=controller.layers[0].stateMachine.AddAnyStateTransition(ast);tr.hasExitTime=false;tr.duration=.05f;tr.AddCondition(AnimatorConditionMode.If,0,state);var back=ast.AddTransition(controller.layers[0].stateMachine.states.First(x=>x.state.name=="idle").state);back.hasExitTime=true;back.exitTime=1;back.duration=.05f;}}
  controller.layers[0].stateMachine.defaultState=idle;var moving=idle.AddTransition(walk);moving.hasExitTime=false;moving.duration=.05f;moving.AddCondition(AnimatorConditionMode.Greater,.1f,"Speed");var stopping=walk.AddTransition(idle);stopping.hasExitTime=false;stopping.duration=.05f;stopping.AddCondition(AnimatorConditionMode.Less,.1f,"Speed");return controller;
 }
 public static void Assemble(){try{var spec=Spec;Folder("Assets/YOE/Scenes");Folder("Assets/YOE/Prefabs");foreach(var path in Directory.GetFiles("Assets/YOE/Art","*.png"))Import(path.Replace('\\','/'));
  var ground=Square("placeholder-ground",spec.theme=="winter"?new Color(.8f,.9f,1):new Color(.22f,.55f,.28f));var hero=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/YOE/Art/idle-000.png");if(!hero)hero=Square("placeholder-hero",new Color(.95f,.78f,.45f));var coin=Square("placeholder-coin",Color.yellow);var enemy=Square("placeholder-enemy",new Color(.9f,.2f,.3f));var controller=Animations(hero);var buildScenes=new List<EditorBuildSettingsScene>();var sceneReports=new List<string>();
  for(int level=0;level<spec.levels;level++){var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var camera=new GameObject("Main Camera");camera.tag="MainCamera";camera.AddComponent<AudioListener>();var cam=camera.AddComponent<Camera>();cam.orthographic=true;cam.orthographicSize=6;cam.backgroundColor=spec.theme=="night"?new Color(.04f,.08f,.18f):new Color(.6f,.8f,1);camera.transform.position=new Vector3(8,2,-10);camera.AddComponent<YoeCamera>();new GameObject("YOE Game").AddComponent<YoeGame>();var grid=new GameObject("Level Grid");grid.AddComponent<Grid>();var tiles=new GameObject("Ground Tilemap");tiles.transform.SetParent(grid.transform);var map=tiles.AddComponent<Tilemap>();tiles.AddComponent<TilemapRenderer>();tiles.AddComponent<TilemapCollider2D>();var tile=ScriptableObject.CreateInstance<Tile>();tile.sprite=ground;tile.colliderType=Tile.ColliderType.Grid;string tp="Assets/YOE/Art/GroundTile.asset";if(!File.Exists(tp))AssetDatabase.CreateAsset(tile,tp);else tile=AssetDatabase.LoadAssetAtPath<Tile>(tp);
   for(int x=-4;x<38;x++)for(int y=-3;y<0;y++)map.SetTile(new Vector3Int(x,y,0),tile);var rng=new System.Random(spec.seed+level);if(spec.genre=="platformer")for(int p=0;p<4;p++){float x=6+p*6,y=1+(p%2);SpriteObject("Reachable platform "+p,ground,new Vector2(x,y),new Vector2(3, .35f),true);}else for(int y=1;y<14;y++){map.SetTile(new Vector3Int(-3,y,0),tile);map.SetTile(new Vector3Int(36,y,0),tile);}var player=SpriteObject("Hero",hero,new Vector2(1,2),Vector2.one,true);player.tag="Player";var rb=player.AddComponent<Rigidbody2D>();rb.gravityScale=spec.genre=="topdown"?0:2;rb.freezeRotation=true;player.AddComponent<YoePlayer>();player.AddComponent<Animator>().runtimeAnimatorController=controller;PrefabUtility.SaveAsPrefabAsset(player,"Assets/YOE/Prefabs/Hero.prefab");
   for(int i=0;i<spec.coins;i++){var c=SpriteObject("Coin "+i,coin,new Vector2(3+i*28f/spec.coins,1.3f+(float)rng.NextDouble()*.5f),new Vector2(.3f,.3f),true);c.GetComponent<BoxCollider2D>().isTrigger=true;c.AddComponent<YoeItem>().kind="coin";}
   for(int i=0;i<3;i++){var en=SpriteObject((level==4&&i==2)?"Boss placeholder":"Enemy "+i,enemy,new Vector2(8+i*8,.7f),new Vector2(.7f,.8f),true);en.AddComponent<YoeEnemy>().speed=spec.enemySpeed;}
   var cp=SpriteObject("Checkpoint",coin,new Vector2(16,1),new Vector2(.3f,1),true);cp.GetComponent<BoxCollider2D>().isTrigger=true;cp.AddComponent<YoeItem>().kind="checkpoint";var exit=SpriteObject("Next level",coin,new Vector2(33,1.5f),new Vector2(.5f,3),true);exit.GetComponent<BoxCollider2D>().isTrigger=true;exit.AddComponent<YoeItem>().kind="exit";string sp="Assets/YOE/Scenes/Level"+(level+1)+".unity";EditorSceneManager.SaveScene(scene,sp);buildScenes.Add(new EditorBuildSettingsScene(sp,true));sceneReports.Add("{\"hierarchy\":["+string.Join(",",scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<Transform>(true)).Select(tr=>Q(tr.name)))+"],\"scene\":"+Q(sp)+",\"coins\":"+spec.coins+",\"enemies\":3,\"player\":true,\"tilemap\":true}");
  }
  EditorBuildSettings.scenes=buildScenes.ToArray();var atlasPath="Assets/YOE/Art/Game.spriteatlas";if(File.Exists(atlasPath))AssetDatabase.DeleteAsset(atlasPath);var atlas=new SpriteAtlas();atlas.Add(new UnityEngine.Object[]{AssetDatabase.LoadAssetAtPath<DefaultAsset>("Assets/YOE/Art")});AssetDatabase.CreateAsset(atlas,atlasPath);PlayerSettings.companyName="YOEAI";PlayerSettings.productName=spec.title;PlayerSettings.defaultScreenWidth=1280;PlayerSettings.defaultScreenHeight=720;AssetDatabase.SaveAssets();Report("scene-report.json","{\"passed\":true,\"placeholderArt\":true,\"input\":\"Unity built-in legacy input; new Input System package absent\",\"scenes\":["+string.Join(",",sceneReports)+"]}");Validate();
 }catch(Exception e){Debug.LogException(e);Report("scene-report.json","{\"passed\":false,\"error\":"+Q(e.Message)+"}");EditorApplication.Exit(2);}}
 public static void Validate(){try{var checks=new List<string>();foreach(var bs in EditorBuildSettings.scenes){var scene=EditorSceneManager.OpenScene(bs.path);var roots=scene.GetRootGameObjects();if(!roots.SelectMany(r=>r.GetComponentsInChildren<YoePlayer>(true)).Any())throw new Exception("Missing player "+bs.path);if(!roots.SelectMany(r=>r.GetComponentsInChildren<TilemapCollider2D>(true)).Any())throw new Exception("Missing ground collision");foreach(var r in roots)foreach(var tr in r.GetComponentsInChildren<Transform>(true))if(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(tr.gameObject)>0)throw new Exception("Missing script: "+tr.name);foreach(var sr in roots.SelectMany(r=>r.GetComponentsInChildren<SpriteRenderer>(true)))if(!sr.sprite)throw new Exception("Missing sprite "+sr.name);checks.Add(Q(bs.path));}if(checks.Count!=Spec.levels)throw new Exception("Incorrect scene count");if(Spec.jump*Spec.jump/(2*19.62f)<2.1f&&Spec.genre=="platformer")throw new Exception("Jump height too low for upper platforms. Increase jump to at least 9.1.");Report("validation.json","{\"passed\":true,\"compiled\":true,\"checks\":[\"scene loading\",\"player\",\"tilemap collision\",\"missing scripts\",\"sprite references\",\"jump height estimate\"],\"scenes\":["+string.Join(",",checks)+"],\"manualPlaytestRequired\":true}");}catch(Exception e){Debug.LogException(e);Report("validation.json","{\"passed\":false,\"error\":"+Q(e.Message)+"}");EditorApplication.Exit(3);}}
 public static void Build(){Validate();try{string[] args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"-yoeTarget");string target=i>=0&&i+1<args.Length?args[i+1]:"Windows";var bt=target=="WebGL"?BuildTarget.WebGL:BuildTarget.StandaloneWindows64;string output=target=="WebGL"?"Builds/WebGL":"Builds/Windows/Game.exe";Directory.CreateDirectory(Path.GetDirectoryName(output));var result=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=EditorBuildSettings.scenes.Select(s=>s.path).ToArray(),locationPathName=output,target=bt,options=BuildOptions.Development});bool ok=result.summary.result==BuildResult.Succeeded;Report("build-report.json","{\"passed\":"+(ok?"true":"false")+",\"target\":"+Q(target)+",\"bytes\":"+result.summary.totalSize+",\"errors\":"+result.summary.totalErrors+",\"warnings\":"+result.summary.totalWarnings+"}");if(!ok)EditorApplication.Exit(4);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(4);}}
}
